using System.Text.Json; namespace KeHoachDaNgoai.Helpers; public static class UserSettings { static string FilePath=>Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"KeHoachDaNgoai","usersettings.json"); public static string Language {get;set;}="vi"; public static void Load(){try{if(File.Exists(FilePath)){using var d=JsonDocument.Parse(File.ReadAllText(FilePath));Language=d.RootElement.GetProperty("Language").GetString()??"vi";}}catch{Language="vi";}} public static void Save(){Directory.CreateDirectory(Path.GetDirectoryName(FilePath)!);File.WriteAllText(FilePath,JsonSerializer.Serialize(new{Language}));} }